import{_ as e}from"./chunks/folders.9ioZn9MV.js";import{_ as o,c as r,o as s,a2 as t}from"./chunks/framework.CIiVzG-O.js";const h=JSON.parse('{"title":"Comparar carpetas","description":"Vea los archivos nuevos, modificados y ausentes en dos carpetas, filtre el árbol y sincronice ambos lados.","frontmatter":{"title":"Comparar carpetas","description":"Vea los archivos nuevos, modificados y ausentes en dos carpetas, filtre el árbol y sincronice ambos lados."},"headers":[],"relativePath":"es/guide/folders.md","filePath":"es/guide/folders.md","lastUpdated":1794296122000}'),i={name:"es/guide/folders.md"};function n(l,a,d,c,p,u){return s(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="comparar-carpetas" tabindex="-1">Comparar carpetas <a class="header-anchor" href="#comparar-carpetas" aria-label="Permalink to &quot;Comparar carpetas&quot;">​</a></h1><p>Cuando dos carpetas deberían coincidir —una copia de trabajo y su copia de seguridad, una exportación antigua y otra nueva— compararlas archivo por archivo es un engorro. qDiff muestra todo el árbol de una vez.</p><img src="'+e+'" alt="Dos árboles de carpetas con estados de archivo coloreados" class="guide-shot"><h2 id="abra-dos-carpetas" tabindex="-1">Abra dos carpetas <a class="header-anchor" href="#abra-dos-carpetas" aria-label="Permalink to &quot;Abra dos carpetas&quot;">​</a></h2><p>Arrastre dos carpetas a la ventana o elíjalas desde <strong>Archivo → Abrir</strong>. Las carpetas dentro de carpetas también se comparan, para que vea el panorama completo.</p><h2 id="lea-el-arbol-de-un-vistazo" tabindex="-1">Lea el árbol de un vistazo <a class="header-anchor" href="#lea-el-arbol-de-un-vistazo" aria-label="Permalink to &quot;Lea el árbol de un vistazo&quot;">​</a></h2><ul><li><strong>Verde</strong> — un archivo que solo existe en un lado.</li><li><strong>Naranja</strong> — el nombre coincide pero el contenido difiere.</li><li><strong>Rojo</strong> — un archivo que falta en el otro lado.</li><li><strong>Gris</strong> — los dos lados coinciden.</li></ul><h2 id="muestre-solo-lo-que-importa" tabindex="-1">Muestre solo lo que importa <a class="header-anchor" href="#muestre-solo-lo-que-importa" aria-label="Permalink to &quot;Muestre solo lo que importa&quot;">​</a></h2><p>Use los filtros por estado para ocultar todo lo que ya coincide, o escriba parte de un nombre para reducir la lista. Puede elegir una comprobación rápida solo por nombre o pedir a qDiff que lea también el contenido, algo útil cuando una copia de seguridad parece correcta pero podría estar desactualizada por dentro.</p><p>Incluso las carpetas grandes se abren rápido, así que no se quedará mirando una barra de progreso.</p><h2 id="ponga-todo-en-orden-desde-la-lista" tabindex="-1">Ponga todo en orden desde la lista <a class="header-anchor" href="#ponga-todo-en-orden-desde-la-lista" aria-label="Permalink to &quot;Ponga todo en orden desde la lista&quot;">​</a></h2><p>Copie un archivo al otro lado, elimine un sobrante o sincronice todo un grupo, siempre desde el mismo árbol. No hace falta volver al Finder.</p><div class="tip custom-block"><p class="custom-block-title">Puede explorar sin miedo</p><p>No se cambia nada en el disco hasta que usted elige una acción. Examinar y filtrar una comparación es completamente seguro.</p></div><p>A continuación: <a href="./projects.html">revise un proyecto antes de confirmar los cambios</a>.</p>',14)])])}const f=o(i,[["render",n]]);export{h as __pageData,f as default};
